import{describe,it,expect}from"vitest";describe("Search Functionality Unit Tests",()=>{const e=[{title:"Taj Mahal",category:"Monuments",tags:["heritage","agra"]},{title:"Butter Chicken",category:"Cuisine",tags:["food","punjab"]},{title:"Diwali Festival",category:"Festivals",tags:["lights","national"]}];it("filters items based on search query",()=>{const t=t=>{const a=t.toLowerCase().trim();return e.filter(e=>e.title.toLowerCase().includes(a)||e.category.toLowerCase().includes(a)||e.tags.some(e=>e.toLowerCase().includes(a)))};expect(t("taj")).toHaveLength(1),expect(t("heritage")).toHaveLength(1),expect(t("food")).toHaveLength(1),expect(t("nonexistent")).toHaveLength(0)}),it("highlights search query in text",()=>{expect(((e,t)=>{if(!t)return e;const a=new RegExp(`(${t})`,"gi");return e.replace(a,"<mark>$1</mark>")})("Taj Mahal","Taj")).toBe("<mark>Taj</mark> Mahal")})});